namespace Encspect.Formats.Wav;

// What each WAV node is, in the words the report shows next to it. Constants only. The sources are Microsoft's "Multimedia Programming
// Interface and Data Specifications 1.0" (the RIFF specification), its "Multimedia Data Standards Update" of April 1994 (the multimedia
// update), the WAVEFORMATEX documentation and mmreg.h, and the EBU's Tech 3285 with its supplements and Tech 3306.
internal static class Explain
{
    public const string AfterEmbeddedTag = "Bytes after an ID3v2 tag that lies inside the RIFF chunk, which breaks the chain of chunks; the analyzer does not read them as chunks.";
    public const string TrailingData = "Bytes after the end of the RIFF chunk that no tag parser recognized.";
    public const string UnreadData = "Bytes where a chunk should start but no chunk header does: its ID is not four printable characters. The analyzer does not read them.";
    public const string FurtherChunks = "More chunks, which the report reads no further: it lists at most 2,048 chunks at one level.";
    public const string ExtraData = "Bytes after the fields of the chunk, which the specification does not use.";

    public static string RiffChunk(string magic) => magic switch
    {
        "RIFX" => "The RIFX chunk that holds the whole file: the big-endian counterpart of RIFF, with the integers in Motorola byte order (RIFF specification, \"About the RIFF Tagged File Format\"). Its form type WAVE makes it a waveform audio file.",
        "RF64" => "The RF64 chunk that holds the whole file: RIFF with 64-bit sizes, which the ds64 chunk gives (EBU Tech 3306). Its form type WAVE makes it a waveform audio file.",
        _ => "The RIFF chunk that holds the whole file: a chunk ID, a size and a form type, followed by the chunks (RIFF specification, \"RIFF Forms\"). Its form type WAVE makes it a waveform audio file.",
    };

    public const string RiffId = "The first four bytes of the file: RIFF for little-endian integers, RIFX for big-endian ones, RF64 for 64-bit sizes.";
    public const string RiffSize = "The size of the RIFF chunk's data in bytes: the form type and all the chunks, not the ID and this field. A writer that cannot go back leaves 0 or 0xFFFFFFFF.";
    public const string FormType = "The form type of the RIFF chunk. WAVE makes the file a waveform audio file (RIFF specification, \"Waveform Audio File Format\").";
    public const string ChunkId = "The ID of the chunk: four ASCII characters, padded on the right with blanks (RIFF specification, \"Chunks\").";
    public const string ChunkSize = "The size of the chunk's data in bytes, not counting the ID, this field or the pad byte (RIFF specification, \"Chunks\").";
    public const string ChunkSizeRf64 = "The size of the chunk's data in bytes. In an RF64 file 0xFFFFFFFF means the size is in the ds64 chunk (EBU Tech 3306, section 3.4).";
    public const string PadByte = "A byte of zero after a chunk whose size is odd, which keeps every chunk at an even offset (RIFF specification, \"Chunks\").";
    public const string UnknownChunk = "A chunk the analyzer does not read. A reader skips the chunks it does not know (RIFF specification, \"Waveform Audio File Format\").";

    public const string FormatChunk = "The fmt chunk: the format of the audio in the data chunk, a WAVEFORMATEX (RIFF specification, \"WAVE Format Chunk\"). It comes before the data chunk.";
    public const string FormatTag = "The format tag, wFormatTag: the coding of the audio. 1 is PCM, 3 IEEE floating point, 0xFFFE the extensible format whose sub-format names the coding (mmreg.h).";
    public const string Channels = "The number of channels, nChannels of the WAVEFORMATEX.";
    public const string SamplesPerSecond = "The sample rate in Hz, nSamplesPerSec of the WAVEFORMATEX.";
    public const string AverageBytesPerSecond = "The average number of bytes per second of the data, nAvgBytesPerSec of the WAVEFORMATEX. For PCM it equals the sample rate times the block alignment.";
    public const string BlockAlignment = "The block alignment in bytes, nBlockAlign of the WAVEFORMATEX: the size of one sample frame for PCM, and the unit a player processes for other formats.";
    public const string BitsPerSample = "The bits per sample of one channel, wBitsPerSample of the WAVEFORMATEX; the container size for PCM, and 0 for codings that have no such size.";
    public const string CodecSpecificDataSize = "The number of bytes of format-specific data after the WAVEFORMATEX, cbSize.";
    public const string CodecSpecificData = "Bytes the format defines, which follow the WAVEFORMATEX; the analyzer shows their size only.";
    public const string ValidBitsPerSample = "The number of bits of each sample that hold audio, wValidBitsPerSample of the WAVEFORMATEXTENSIBLE; the rest of the container is zero (ksmedia.h documentation).";
    public const string ChannelMask = "Which speakers the channels feed: a bit for each speaker position, dwChannelMask of the WAVEFORMATEXTENSIBLE. The channels are in the order of the bits.";
    public const string MaskSpeakers = "The speakers the set bits stand for, in the order of the channels in the data.";
    public const string SubFormat = "A GUID whose first 32 bits are the format tag of the coding when the other twelve bytes are Microsoft's base GUID, SubFormat of the WAVEFORMATEXTENSIBLE.";
    public const string SamplesPerBlock = "The number of samples of each channel in one block of the data (Microsoft ADPCM, IMA ADPCM and GSM 6.10).";
    public const string CoefficientSets = "The number of pairs of prediction coefficients that follow, wNumCoef (Microsoft ADPCM); the standard seven come first.";
    public const string Coefficients = "The prediction coefficients, fixed-point numbers with 8 fractional bits, in pairs (Microsoft ADPCM).";
    public const string CoefficientSet = "One pair of prediction coefficients, iCoef1 and iCoef2; divided by 256 they are the weights of the two previous samples.";
    public const string MpegLayer = "The MPEG audio layers the stream holds, fwHeadLayer of the MPEG1WAVEFORMAT: bit 0 is Layer I, bit 1 Layer II, bit 2 Layer III.";
    public const string MpegBitrate = "The bitrate of the stream in bits per second, dwHeadBitrate; 0 if it varies or is not a standard rate.";
    public const string MpegMode = "The channel modes the stream holds, fwHeadMode: bit 0 stereo, bit 1 joint stereo, bit 2 dual channel, bit 3 single channel.";
    public const string MpegModeExtension = "The joint-stereo mode extensions the stream holds, fwHeadModeExt: one bit for each value of the frame header's mode extension.";
    public const string MpegEmphasis = "The emphasis the stream needs undone, wHeadEmphasis: 1 none, 2 50/15 ms, 3 reserved, 4 CCITT J.17.";
    public const string MpegFlags = "The frame header bits set in any frame, fwHeadFlags: private, copyright, original, protection and the MPEG-1 ID bit.";
    public const string PtsLow = "The low 32 bits of the presentation time stamp of the first frame, dwPTSLow; 0 when the stream has no system layer.";
    public const string PtsHigh = "The high bit of the 33-bit presentation time stamp of the first frame, dwPTSHigh.";
    public const string Mp3Id = "The identifier, wID of the MPEGLAYER3WAVEFORMAT (mmreg.h): 1 for MPEG frames, 2 for frames of constant size.";
    public const string Mp3Flags = "The padding flags, fdwFlags of the MPEGLAYER3WAVEFORMAT: whether the padding bit is as the ISO standard has it, always on or always off.";
    public const string Mp3BlockSize = "The size of a block in bytes, nBlockSize of the MPEGLAYER3WAVEFORMAT.";
    public const string Mp3FramesPerBlock = "The number of frames in a block, nFramesPerBlock of the MPEGLAYER3WAVEFORMAT.";
    public const string Mp3CodecDelay = "The delay of the codec in samples, nCodecDelay of the MPEGLAYER3WAVEFORMAT.";

    public const string FactChunk = "The fact chunk: the number of samples of each channel in the audio. The specification requires it for every format but PCM (RIFF specification, \"FACT Chunk\").";
    public const string FactSamples = "The number of samples of each channel, dwFileSize in the specification's notation; 0xFFFFFFFF in an RF64 file means the ds64 chunk gives it.";
    public const string FactFurther = "Fields after the sample count, which the specification keeps for later formats.";
    public const string DataChunk = "The data chunk: the audio samples, in the coding the fmt chunk states (RIFF specification, \"Storage of WAVE Data\").";
    public const string Statistics = "Figures over the audio the file describes: its length, rate, channels and the bits of its samples.";
    public const string StatCodec = "The coding of the audio, from the format tag of the fmt chunk.";
    public const string StatSampleFrames = "The number of sample frames in the data chunk: the bytes of the chunk divided by the block alignment. A sample frame holds one sample of every channel.";
    public const string StatSamples = "The number of samples of each channel, from the fact chunk.";
    public const string StatDuration = "The length of the audio: the samples divided by the sample rate.";
    public const string StatRate = "The sample rate in Hz, from the fmt chunk.";
    public const string StatChannels = "The number of channels, from the fmt chunk.";
    public const string StatLayout = "The speaker each channel feeds, in the order of the channels in the data; from the channel mask, or, without one, front left and right for two channels and the front center for one.";
    public const string StatBits = "The bits of each sample that hold audio.";
    public const string StatContainerBits = "The bits a sample takes in the data chunk, a whole number of bytes; larger than the bits of audio when the format states fewer valid bits.";
    public const string StatSampleFormat = "How a sample is coded: 8-bit PCM is unsigned, wider PCM is signed, floating-point samples are IEEE 754 numbers (RIFF specification, \"Data Format of the Samples\").";
    public const string StatByteOrder = "The order of the bytes of a sample: little-endian in RIFF and RF64 files, big-endian in RIFX files.";
    public const string StatBitrate = "The average bitrate of the data chunk: its bytes times 8 over the length of the audio.";

    public const string Ds64Chunk = "The ds64 chunk of an RF64 file: the 64-bit sizes of the RIFF chunk, of the data chunk and of the fact chunk's sample count, and the sizes of other large chunks. It comes first after the RF64 header (EBU Tech 3306, section 3.4).";
    public const string Ds64RiffSize = "The size of the RF64 chunk in bytes, replacing the 32-bit size field of the header.";
    public const string Ds64DataSize = "The size of the data chunk in bytes, replacing its 32-bit size field.";
    public const string Ds64SampleCount = "The number of samples of each channel, replacing the sample length of the fact chunk.";
    public const string Ds64TableLength = "The number of entries in the table of other chunks' sizes.";
    public const string Ds64Table = "The sizes of chunks other than the data chunk whose 32-bit size field holds 0xFFFFFFFF, each with its chunk ID.";
    public const string Ds64Entry = "A chunk ID and a 64-bit size, ChunkSize64 in Tech 3306.";

    public const string BextChunk = "The Broadcast Audio Extension chunk of the Broadcast Wave Format: the origin of the recording, its time reference, and in newer versions a UMID and loudness values (EBU Tech 3285, section 2.3).";
    public const string BextDescription = "A free description of the sound, up to 256 characters (EBU Tech 3285, section 2.3).";
    public const string BextOriginator = "The name of the originator or producer of the file, up to 32 characters.";
    public const string BextOriginatorReference = "A reference the originating organization gave the file, up to 32 characters.";
    public const string BextDate = "The date of creation of the sound, yyyy-mm-dd with any separator.";
    public const string BextTime = "The time of creation of the sound, hh-mm-ss with any separator.";
    public const string BextTimeReference = "The time code of the first sample: the number of samples since midnight, a 64-bit number.";
    public const string BextVersion = "The version of the Broadcast Wave Format: 1 adds the UMID, 2 the loudness values.";
    public const string BextUmid = "The SMPTE Unique Material Identifier, 64 bytes; present from version 1, and a basic UMID takes the first 32.";
    public const string BextLoudnessValue = "The integrated loudness of the file, in LUFS, stored times 100 (EBU Tech 3285, section 2.4); version 2 and later.";
    public const string BextLoudnessRange = "The loudness range of the file, in LU, stored times 100; version 2 and later.";
    public const string BextMaxTruePeak = "The maximum true peak level of the file, in dBTP, stored times 100; version 2 and later.";
    public const string BextMaxMomentary = "The highest momentary loudness of the file, in LUFS, stored times 100; version 2 and later.";
    public const string BextMaxShortTerm = "The highest short-term loudness of the file, in LUFS, stored times 100; version 2 and later.";
    public const string BextReserved = "180 bytes reserved for extension, zero in versions 1 and 2.";
    public const string BextCodingHistory = "The history of the coding of the sound: strings ended by a carriage return and a line feed, one for each coding process.";

    public const string CueChunk = "The cue chunk: positions in the audio, each with a name that other chunks refer to (RIFF specification, \"Cue-Points Chunk\").";
    public const string CueCount = "The number of cue points in the chunk.";
    public const string CueTable = "The cue points: records of 24 bytes.";
    public const string CuePoint = "One cue point (RIFF specification, \"Cue-Points Chunk\").";
    public const string CueName = "The name of the cue point, dwName; unique in the file, and what labels and playlist segments refer to.";
    public const string CuePosition = "The sample position of the cue point in the play order, dwPosition.";
    public const string CueChunkId = "The ID of the chunk that holds the cue point, fccChunk: data for a file with one data chunk.";
    public const string CueChunkStart = "The offset of the start of the chunk that holds the cue point, dwChunkStart: 0 for a single data chunk.";
    public const string CueBlockStart = "The offset of the block that holds the cue point, dwBlockStart: 0 for PCM; a decoder of compressed data starts here.";
    public const string CueSampleOffset = "The sample offset of the cue point, dwSampleOffset: from the start of the data chunk for PCM, from the start of the block otherwise.";
    public const string PlaylistChunk = "The playlist chunk: the order in which sections between cue points are played (RIFF specification, \"Playlist Chunk\").";
    public const string PlaylistCount = "The number of play segments in the chunk.";
    public const string PlaylistTable = "The play segments: records of 12 bytes.";
    public const string PlaylistSegment = "One play segment (RIFF specification, \"Playlist Chunk\").";
    public const string PlaylistName = "The name of the cue point where the segment starts, dwName.";
    public const string PlaylistLength = "The length of the segment in samples, dwLength.";
    public const string PlaylistLoops = "How many times the segment is played, dwLoops.";
    public const string SampleChunk = "The sample chunk: what a sampling keyboard needs to use the file as an instrument, with its loops (multimedia update, \"smpl (Sample) Chunk\").";
    public const string SmplManufacturer = "The MIDI Manufacturers Association code of the intended device; the high byte says whether one or three bytes of the code are valid. 0 if the sample is for no device in particular.";
    public const string SmplProduct = "The product code of the intended device; 0 if the sample is for none.";
    public const string SmplPeriod = "The length of one sample in nanoseconds: normally the inverse of the sample rate, which this field can fine-tune.";
    public const string SmplUnityNote = "The MIDI note that plays the sample at its original pitch, 0 to 127; 60 is middle C.";
    public const string SmplPitchFraction = "The fraction of a semitone above the unity note; 0x80000000 is half a semitone.";
    public const string SmplSmpteFormat = "The time format of the SMPTE offset: 0 for none, or 24, 25, 29 (30 with frame dropping) or 30 frames per second.";
    public const string SmplSmpteOffset = "A time offset to synchronize the sample to, as hours, minutes, seconds and frames in one byte each.";
    public const string SmplLoopCount = "The number of sample loops that follow the header.";
    public const string SmplDataSize = "The number of bytes of sampler-specific data that follow the loops.";
    public const string SmplLoops = "The sample loops: records of 24 bytes.";
    public const string SmplLoop = "One sample loop (multimedia update, \"smpl (Sample) Chunk\").";
    public const string SmplLoopId = "The name of the loop; it may match a name in the cue chunk.";
    public const string SmplLoopType = "The loop type: 0 forward, 1 alternating forward and backward, 2 backward, 3 to 31 reserved, 32 and up sampler specific.";
    public const string SmplLoopStart = "The first sample of the loop.";
    public const string SmplLoopEnd = "The last sample of the loop, which is played too.";
    public const string SmplLoopFraction = "Fine-tuning of the loop's length in fractions of a sample; 0x80000000 is half a sample.";
    public const string SmplLoopPlayCount = "How many times the loop is played; 0 is an infinite sustain loop.";
    public const string SmplSamplerData = "Bytes only the target sampler understands.";
    public const string InstrumentChunk = "The instrument chunk: the pitch, gain and playable ranges of the sample for a sampling keyboard (multimedia update, \"inst (Instrument) Chunk\").";
    public const string InstNote = "The MIDI note number of the unshifted pitch of the sample, 0 to 127.";
    public const string InstFineTune = "The pitch adjustment in cents needed to hit the unshifted note exactly, -50 to 50.";
    public const string InstGain = "The suggested volume setting in decibels; 0 means no change.";
    public const string InstLowNote = "The lowest MIDI note the sample is suggested for, 0 to 127.";
    public const string InstHighNote = "The highest MIDI note the sample is suggested for, 0 to 127.";
    public const string InstLowVelocity = "The lowest MIDI velocity the sample is suggested for, 0 to 127.";
    public const string InstHighVelocity = "The highest MIDI velocity the sample is suggested for, 0 to 127.";

    public const string ListChunk = "A LIST chunk: a list type followed by chunks, which a reader that does not know the type can still walk through (RIFF specification, \"LIST Chunk\").";
    public const string ListType = "The type of the list: INFO holds text about the file, adtl labels for cue points, wavl pieces of audio and silence.";
    public const string ListContents = "The chunks of the list, which the analyzer does not read because lists nest too deep.";
    public const string InfoListed = "A text chunk of an INFO list: a string ended by a zero byte (RIFF specification, \"INFO List Chunk\").";
    public const string InfoUnlisted = "A chunk of an INFO list that the specification does not list; an INFO list may hold new chunks, which hold text too.";
    public const string InfoText = "The text of the chunk.";
    public const string LablChunk = "A label for a cue point (RIFF specification, \"Associated Data Chunk\").";
    public const string NoteChunk = "A comment on a cue point (RIFF specification, \"Associated Data Chunk\").";
    public const string LtxtChunk = "Text tied to a stretch of the audio that starts at a cue point (RIFF specification, \"Text with Data Length Information\").";
    public const string FileChunk = "A file tied to a cue point, such as a bitmap or a text file (RIFF specification, \"Embedded File Information\").";
    public const string LabelName = "The name of the cue point the chunk is attached to, dwName; it matches one in the cue chunk.";
    public const string LabelText = "The text, ended by a zero byte.";
    public const string LtxtLength = "The number of samples the text covers, dwSampleLength.";
    public const string LtxtPurpose = "What the text is for, dwPurpose: a four-character code such as scrp for script text or capt for captions.";
    public const string LtxtCountry = "The country code of the text, wCountry.";
    public const string LtxtLanguage = "The language code of the text, wLanguage.";
    public const string LtxtDialect = "The dialect code of the text, wDialect.";
    public const string LtxtCodePage = "The code page of the text, wCodePage.";
    public const string FileMediaType = "The type of the file, dwMedType: the form type if the file is a RIFF form, or 0.";
    public const string FileData = "The embedded file.";
    public const string SlntChunk = "A stretch of silence in a wavl list: the player holds the last sample (RIFF specification, \"Storage of WAVE Data\").";
    public const string SlntSamples = "The number of samples of silence, dwSamples.";
    public const string CsetChunk = "The character set chunk: the code page, country and language of the text in the file (RIFF specification, \"CSET (Character Set) Chunk\").";
    public const string CsetCodePage = "The code page of the text, wCodePage; 0 or absent means ISO 8859-1.";
    public const string CsetCountry = "The country code, wCountryCode; 0 means none, 1 the USA.";
    public const string CsetLanguage = "The language code, wLanguageCode.";
    public const string CsetDialect = "The dialect code, wDialect.";
    public const string JunkChunk = "A JUNK chunk: filler of any size, with no meaning (RIFF specification, \"JUNK (Filler) Chunk\"). A writer reserves one to turn it into a ds64 chunk later.";
    public const string PadChunk = "A PAD chunk: filler, as JUNK is (multimedia update, \"PAD (Filler) Chunk\").";
    public const string Filler = "The filler bytes.";
    public const string Id3Chunk = "An ID3v2 tag stored in a chunk. The analyzer hands the chunk's data to the ID3v2 parser.";
    public const string AxmlChunk = "The axml chunk: XML metadata, such as the Audio Definition Model (EBU Tech 3285 supplement 5).";
    public const string IxmlChunk = "The iXML chunk: XML metadata that location recorders and editors write. The analyzer shows its text.";
    public const string XmlText = "The XML text of the chunk, ended by zero bytes when the writer padded it.";
    public const string ChnaChunk = "The chna chunk: for each track of the audio, the IDs of its description in the Audio Definition Model (EBU Tech 3285 supplement 7).";
    public const string ChnaTracks = "The number of tracks used in the file.";
    public const string ChnaUids = "The number of track UIDs used in the file; a track may have several, for different stretches of time.";
    public const string ChnaTable = "The ID structures: records of 40 bytes, of which unused ones are zero.";
    public const string ChnaEntry = "One ID structure: a track and the IDs of its audioTrackUID, audioTrackFormat and audioPackFormat.";
    public const string ChnaIndex = "The index of the track in the file, from 1; 0 for an unused structure.";
    public const string ChnaUid = "The audioTrackUID, the characters ATU_ and eight hexadecimal digits.";
    public const string ChnaTrackRef = "The reference to the audioTrackFormatID, AT_ and hexadecimal digits.";
    public const string ChnaPackRef = "The reference to the audioPackFormatID, AP_ and eight hexadecimal digits, or zeros.";
    public const string LevlChunk = "The peak envelope chunk: the peaks of the audio at a set interval, for drawing it quickly (EBU Tech 3285 supplement 3). The analyzer does not read it.";
    public const string LinkChunk = "The link chunk: XML that links the files of a recording split over several (EBU Tech 3285 supplement 4). The analyzer does not read it.";
    public const string DbmdChunk = "The Dolby metadata chunk (EBU Tech 3285 supplement 6). The analyzer does not read it.";
    public const string QltyChunk = "The quality chunk of the capturing report: the events that affected the quality of the capture, and a cue sheet (EBU Tech 3285 supplement 2). The analyzer does not read it.";
    public const string R64mChunk = "The marker chunk of RF64: markers with 64-bit positions and labels (EBU Tech 3306, annex A.4). The analyzer does not read it.";
}
